using System.Linq;using NUnit.Framework;using UnityEditor;using UnityEngine;using Rootborn.Game.Careers;
namespace Rootborn.Tests.EditMode.Careers{
public sealed class CenteredFacilityEntranceAssetTests{
[TestCase("chef",1)][TestCase("chef",2)][TestCase("chef",3)][TestCase("emergencycare",2)][TestCase("emergencycare",3)][TestCase("interior",3)][TestCase("soldier",1)][TestCase("soldier",2)][TestCase("soldier",3)]public void ReviewedCentralDoor_AlignsInteractionAndOpenApproachCells(string family,int level){var v=AssetDatabase.LoadAssetAtPath<FacilityVisualDefinition>("Assets/Data/Careers/FacilityVisuals/"+family+"_lv"+level+".asset");Assert.That(v,Is.Not.Null);Assert.That(v.EntranceLocalPosition,Is.EqualTo(v.SpriteOffset),"Interaction point must match the centered floor-contact sprite pivot");float center=(v.SiteSize.x-1)*.5f;var expected=Enumerable.Range(0,v.SiteSize.x).Where(x=>Mathf.Abs(x-center)<=.5f).Select(x=>new Vector2Int(x,0)).ToArray();Assert.That(v.EntranceCells,Is.EquivalentTo(expected));Assert.That(v.ApproachCells,Is.EquivalentTo(expected.Select(c=>c+Vector2Int.down)));Assert.That(v.CollisionCells.Intersect(expected),Is.Empty);Assert.That(v.CollisionCells.Count,Is.EqualTo(v.SiteSize.x*v.SiteSize.y-v.EntranceCells.Count),"Solid building must occupy its footprint except the doorway");Assert.That(v.IsValid,Is.True);}
}}
